const device = $input.first().json;
const status = device.status || 'unknown';
const cpu = device.cpu_percent ?? 'N/A';
const memory = device.memory_percent ?? 'N/A';
const isAbnormal = cpu > 90 || status === 'critical';

return [{ json: {
  device_id: device.device_id,
  cpu_percent: cpu,
  memory_percent: memory,
  network_status: device.network_status || 'N/A',
  status: status,
  is_abnormal: isAbnormal,
  summary: `設備 ${device.device_id}：CPU ${cpu}%，Memory ${memory}%，狀態 ${status}${isAbnormal ? ' ⚠️ 異常' : ' ✅ 正常'}`
} }];
